using System.Net;
using System.Text;
using System.Text.Json;
using PaymentAuthorization.Domain;
using PaymentAuthorization.Infrastructure;

namespace PaymentAuthorization.IntegrationTest.PaymentGateway;

public sealed class HttpPaymentGatewayTests : IDisposable
{
    private readonly FakeProvider provider = new();

    private HttpPaymentGateway Gateway() => new(new HttpClient { BaseAddress = provider.BaseAddress });

    private Task<AuthorizationOutcome> Authorize(string reference = "ORD-1", decimal amount = 12.50m, string currency = "eur") =>
        Gateway().AuthorizeAsync(reference, new Money(amount, currency), CancellationToken.None);

    [Fact]
    public async Task Sends_a_POST_with_the_agreed_json_contract()
    {
        provider.Respond(200, """{"status":"approved"}""");

        await Authorize("ORD-1", 12.50m, "eur");

        var request = Assert.Single(provider.Requests);
        Assert.Equal("POST", request.Method);
        Assert.Equal("/v1/authorizations", request.Path);
        Assert.StartsWith("application/json", request.ContentType);
        using var json = JsonDocument.Parse(request.Body);
        var root = json.RootElement;
        Assert.Equal(["amount", "currency", "reference"], root.EnumerateObject().Select(p => p.Name).Order().ToArray());
        Assert.Equal("ORD-1", root.GetProperty("reference").GetString());
        Assert.Equal(JsonValueKind.Number, root.GetProperty("amount").ValueKind);
        Assert.Equal(12.50m, root.GetProperty("amount").GetDecimal());
        Assert.Equal("EUR", root.GetProperty("currency").GetString());
    }

    [Fact]
    public async Task An_approved_status_is_read_as_approved()
    {
        provider.Respond(200, """{"status":"approved"}""");
        Assert.Equal(AuthorizationOutcome.Approved, await Authorize());
    }

    [Fact]
    public async Task A_declined_status_is_read_as_declined()
    {
        provider.Respond(200, """{"status":"declined"}""");
        Assert.Equal(AuthorizationOutcome.Declined, await Authorize());
    }

    [Fact]
    public async Task Extra_fields_in_the_answer_are_ignored()
    {
        provider.Respond(200, """{"id":"auth_9","status":"approved","risk":{"score":3}}""");
        Assert.Equal(AuthorizationOutcome.Approved, await Authorize());
    }

    [Fact]
    public async Task An_unknown_status_is_never_treated_as_approved()
    {
        provider.Respond(200, """{"status":"pending_review"}""");
        Assert.Equal(AuthorizationOutcome.Declined, await Authorize());
    }

    [Fact]
    public async Task An_answer_without_a_status_is_never_treated_as_approved()
    {
        provider.Respond(200, """{"result":"approved"}""");
        Assert.Equal(AuthorizationOutcome.Declined, await Authorize());
    }

    [Fact]
    public async Task A_refused_payment_402_is_read_as_declined()
    {
        provider.Respond(402, """{"error":"card_refused"}""");
        Assert.Equal(AuthorizationOutcome.Declined, await Authorize());
        Assert.Single(provider.Requests);
    }

    [Theory]
    [InlineData(400)]
    [InlineData(401)]
    [InlineData(422)]
    [InlineData(500)]
    [InlineData(503)]
    public async Task Other_failures_surface_instead_of_looking_like_a_decision(int status)
    {
        provider.Respond(status, """{"error":"nope"}""");
        var ex = await Assert.ThrowsAsync<HttpRequestException>(() => Authorize());
        Assert.Equal((HttpStatusCode)status, ex.StatusCode);
    }

    [Fact]
    public async Task A_malformed_answer_surfaces_instead_of_looking_like_a_decision()
    {
        provider.Respond(200, "<html>oops</html>");
        await Assert.ThrowsAnyAsync<JsonException>(() => Authorize());
    }

    public void Dispose() => provider.Dispose();

    private sealed record Received(string Method, string Path, string? ContentType, string Body);

    private sealed class FakeProvider : IDisposable
    {
        private readonly HttpListener listener = new();
        private readonly List<Received> requests = [];
        private int status = 200;
        private string body = "{}";

        public FakeProvider()
        {
            // Retry on the rare port collision between probing and binding.
            for (var attempt = 0; ; attempt++)
            {
                var port = new Random().Next(20000, 60000);
                try
                {
                    listener.Prefixes.Add($"http://127.0.0.1:{port}/");
                    listener.Start();
                    BaseAddress = new Uri($"http://127.0.0.1:{port}");
                    break;
                }
                catch (HttpListenerException) when (attempt < 10)
                {
                    listener.Prefixes.Clear();
                }
            }
            _ = Task.Run(Loop);
        }

        public Uri BaseAddress { get; private set; } = null!;

        public IReadOnlyList<Received> Requests { get { lock (requests) return requests.ToArray(); } }

        public void Respond(int statusCode, string responseBody) { status = statusCode; body = responseBody; }

        private async Task Loop()
        {
            while (listener.IsListening)
            {
                HttpListenerContext context;
                try { context = await listener.GetContextAsync(); }
                catch (Exception) { return; }

                using var reader = new StreamReader(context.Request.InputStream, Encoding.UTF8);
                var received = new Received(context.Request.HttpMethod, context.Request.Url!.AbsolutePath,
                    context.Request.ContentType, await reader.ReadToEndAsync());
                lock (requests) requests.Add(received);

                var bytes = Encoding.UTF8.GetBytes(body);
                context.Response.StatusCode = status;
                context.Response.ContentType = "application/json";
                await context.Response.OutputStream.WriteAsync(bytes);
                context.Response.Close();
            }
        }

        public void Dispose() => listener.Close();
    }
}
